import React, { useEffect, useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import {
  Store,
  Package,
  Plus,
  LogOut,
  ShoppingBag,
  Trash2,
  ArrowRight
} from 'lucide-react';

function SellerDashboard() {
  const navigate = useNavigate();
  const [products, setProducts] = useState([]);
  const [message, setMessage] = useState('');
  const [form, setForm] = useState({
    name: '',
    category: 'Pottery',
    price: '',
    stock: ''
  });

  let user = {};

  try {
    user = JSON.parse(localStorage.getItem('craftlanka_user') || '{}');
  } catch {
    user = {};
  }

  useEffect(() => {
    try {
      const saved = JSON.parse(
        localStorage.getItem('craftlanka_seller_products') || '[]'
      );

      if (Array.isArray(saved)) {
        setProducts(saved.filter((product) => product.sellerEmail === user.email));
      }
    } catch {
      setProducts([]);
    }
  }, [user.email]);

  const handleLogout = () => {
    localStorage.removeItem('craftlanka_user');
    navigate('/login');
  };

  const handleChange = (event) => {
    const { name, value } = event.target;
    setForm((previous) => ({ ...previous, [name]: value }));
  };

  const handleAddProduct = (event) => {
    event.preventDefault();
    setMessage('');

    const price = Number(form.price);
    const stock = Number(form.stock);

    if (!form.name.trim() || !Number.isFinite(price) || price <= 0 ||
        !Number.isInteger(stock) || stock < 0) {
      setMessage('Enter a product name, valid price and stock quantity.');
      return;
    }

    const product = {
      id: `SELL-${Date.now()}`,
      name: form.name.trim(),
      category: form.category,
      price,
      stock,
      sellerEmail: user.email || '',
      createdAt: new Date().toISOString()
    };

    try {
      const allProducts = JSON.parse(
        localStorage.getItem('craftlanka_seller_products') || '[]'
      );

      if (!Array.isArray(allProducts)) {
        throw new Error('Invalid product data');
      }

      const updated = [product, ...allProducts];
      localStorage.setItem('craftlanka_seller_products', JSON.stringify(updated));
      setProducts(updated.filter((item) => item.sellerEmail === user.email));
      setForm({ name: '', category: 'Pottery', price: '', stock: '' });
      setMessage('Product added successfully in this browser demo.');
    } catch {
      setMessage('Unable to save product. Please try again.');
    }
  };

  const handleDelete = (id) => {
    try {
      const allProducts = JSON.parse(
        localStorage.getItem('craftlanka_seller_products') || '[]'
      );

      if (!Array.isArray(allProducts)) return;

      const updated = allProducts.filter(
        (product) => !(product.id === id && product.sellerEmail === user.email)
      );

      localStorage.setItem('craftlanka_seller_products', JSON.stringify(updated));
      setProducts(updated.filter((product) => product.sellerEmail === user.email));
      setMessage('Product removed from this browser demo.');
    } catch {
      setMessage('Unable to remove product.');
    }
  };

  return (
    <main className="dashboard-page">
      <section className="dashboard-welcome seller-welcome">
        <div>
          <p className="eyebrow">ARTISAN WORKSPACE</p>
          <h1>Your craft, <span>your business.</span></h1>
          <p>Manage your handmade products and grow your CraftLanka shop.</p>
          <p className="seller-welcome-name">
            Seller: {user.fullName || 'Artisan'} {user.email ? `· ${user.email}` : ''}
          </p>
        </div>
        <button className="dashboard-logout" onClick={handleLogout}>
          <LogOut size={17} /> Sign Out
        </button>
      </section>

      <section className="dashboard-stats">
        <article className="dashboard-stat">
          <span className="dashboard-stat-icon"><Package size={22} /></span>
          <div><strong>{products.length}</strong><span>My Products</span></div>
        </article>
        <article className="dashboard-stat">
          <span className="dashboard-stat-icon"><Store size={22} /></span>
          <div><strong>Artisan</strong><span>Account Type</span></div>
        </article>
        <article className="dashboard-stat">
          <span className="dashboard-stat-icon"><ShoppingBag size={22} /></span>
          <div><strong>Manage</strong><span>Your Shop</span></div>
        </article>
      </section>

      <section className="dashboard-section">
        <div className="dashboard-section-heading">
          <div>
            <p className="eyebrow">YOUR INVENTORY</p>
            <h2>Add a New Product</h2>
          </div>
          <Link to="/products" className="dashboard-view-link">
            View Marketplace <ArrowRight size={16} />
          </Link>
        </div>

        <form className="seller-product-form" onSubmit={handleAddProduct}>
          <label>
            Product Name
            <input
              name="name"
              value={form.name}
              onChange={handleChange}
              placeholder="e.g. Handmade Clay Vase"
              required
            />
          </label>

          <label>
            Category
            <select name="category" value={form.category} onChange={handleChange}>
              <option>Pottery</option>
              <option>Batik</option>
              <option>Wood Carving</option>
              <option>Handloom</option>
            </select>
          </label>

          <label>
            Price (LKR)
            <input
              type="number"
              name="price"
              value={form.price}
              onChange={handleChange}
              placeholder="2500"
              min="1"
              step="0.01"
              required
            />
          </label>

          <label>
            Stock Quantity
            <input
              type="number"
              name="stock"
              value={form.stock}
              onChange={handleChange}
              placeholder="10"
              min="0"
              step="1"
              required
            />
          </label>

          <button type="submit" className="auth-submit seller-add-button">
            <Plus size={18} /> Add Product
          </button>
        </form>

        {message && <p className="seller-message" role="status">{message}</p>}
      </section>

      <section className="dashboard-section">
        <div className="dashboard-section-heading">
          <div>
            <p className="eyebrow">PRODUCT MANAGEMENT</p>
            <h2>Your Products</h2>
          </div>
          <span className="seller-product-count">{products.length} product(s)</span>
        </div>

        {products.length === 0 ? (
          <div className="seller-empty">
            <Package size={38} />
            <h3>Your shop is waiting for its first product.</h3>
            <p>Use the form above to add a product to your demo inventory.</p>
          </div>
        ) : (
          <div className="seller-products-list">
            {products.map((product) => (
              <article className="seller-product-row" key={product.id}>
                <div className="seller-product-icon"><Store size={22} /></div>
                <div className="seller-product-info">
                  <strong>{product.name}</strong>
                  <span>{product.category} · Stock: {product.stock}</span>
                </div>
                <strong className="seller-product-price">
                  LKR {product.price.toLocaleString('en-LK')}
                </strong>
                <button
                  type="button"
                  className="seller-delete-button"
                  onClick={() => handleDelete(product.id)}
                  aria-label={`Delete ${product.name}`}
                >
                  <Trash2 size={18} />
                </button>
              </article>
            ))}
          </div>
        )}
      </section>
    </main>
  );
}

export default SellerDashboard;
